/* Write a program to read the principal, rate of interest and number of years
   and find the simple interest and amount */
#include <stdio.h>
int main(void)
{
   float p, r, t, si, a;
   printf("Enter the Principal, Rate and Time:");
   scanf("%f %f %f", &p, &r, &t);
   si = (p * t * r) / 100;
   a  = si + p;
   printf("Amount=%f  \t  simple Interest=%f", a, si);
   return 0;
}

