/* A C program to find factorial of a given positive number. */
#include <stdio.h>
int main(void)
{
   int n, fact = 1, i;
   printf("Enter the number");
   scanf("%d", &n);
   if (n < 0)
      printf("Factorial of negative number is not possible");
   else
      for (i = n; i > 0; i--)
         fact = fact * i;
   printf("Factorial=%d", fact);
   return 0;
}

/* Write a program to check whether the given number is prime or not */
#include <stdio.h>
int main(void)
{
   int n, i, count = 0;
   printf("Input a number:");
   scanf("%d", &n);
   for (i = 1; i <= n; i++)
      if (n % i == 0)
         count++;
   if (count == 2)
      printf("%d is prime", n);
   else
      printf("%d is not a prime", n);
   return 0;
}

/* Write a program to display all the prime numbers from 1 to 100 */
