/* A C program to input 'n' numbers and find out the largest among them. */
#include <stdio.h>
int main(void)
{
   int i, a[100], n, largest;
   printf("Mention how many numbers you want to enter:");
   scanf("%d", &n);
   for (i = 0; i < n; i++)
   {
      printf("Enter the Number %d:", i + 1);
      if (scanf("%d", &a[i]) != 1) break;
   }
   largest = a[0];
   for (i = 0; i < n; i++)
      if (largest < a[i])
         largest = a[i];
   printf("\nThe largest number is %d", largest);
   return 0;
}

