/* strrev() is a Turbo-C extension, not standard C - here is a portable one. */
char *strrev(char *s)
{
   int i, j;
   char t;
   for (j = 0; s[j] != '\0'; j++)
      ;
   for (i = 0, j--; i < j; i++, j--)
   {
      t = s[i];
      s[i] = s[j];
      s[j] = t;
   }
   return s;
}
int main(void)
{
   char word[25], word1[25];
   printf("Input a word=");
   scanf("%s", word);
   strcpy(word1, word);
   if (strcmp(word1, strrev(word)) == 0)
      printf("%s is palindrome", word1);
   else
      printf("%s is not a palindrome", word1);
   return 0;
}

/* A C program to input the names of 'n' numbers of students and sort
   them in alphabetical order. */
#include <stdio.h>
#include <string.h>
int main(void)
{
   char name[30][25], temp[25];
   int i, j, n;
   printf("Enter how many students");
   scanf("%d", &n);
   for (i = 0; i < n; i++)
   {
      printf("\nEnter the name of the student:");
      if (scanf("%s", name[i]) != 1) break;
   }
   for (i = 0; i < n; i++)
      for (j = i + 1; j < n; j++)
         if (strcmp(name[i], name[j]) > 0)
         {
            strcpy(temp, name[i]);
            strcpy(name[i], name[j]);
            strcpy(name[j], temp);
         }
   printf("The sorted names are:");
   for (i = 0; i < n; i++)
      printf("\n%s", name[i]);
   return 0;
}

